// This module is intended to be used as an ES module (import ... from './src/api.js').

/**
 * Fetches the first definition for the given English word from dictionaryapi.dev.
 * @param {string} word - The word to look up.
 * @returns {Promise<string>} - A promise that resolves to the definition text.
 * @throws {Error} - If the request fails or no definition is found.
 */
export async function fetchDefinition(word) {
  if (!word) {
    throw new Error('Word must be a non‑empty string');
  }
  const url = `https://api.dictionaryapi.dev/api/v2/entries/en/${encodeURIComponent(word)}`;
  const response = await fetch(url);
  if (!response.ok) {
    // The API returns 404 for unknown words
    const errorInfo = await response.text();
    throw new Error(`Failed to fetch definition: ${response.status} ${response.statusText} – ${errorInfo}`);
  }
  const data = await response.json();
  // data is an array of entries; each entry has meanings -> definitions
  if (!Array.isArray(data) || data.length === 0) {
    throw new Error('No definition data returned');
  }
  const entry = data[0];
  if (!entry.meanings || entry.meanings.length === 0) {
    throw new Error('No meanings found in definition data');
  }
  const meaning = entry.meanings[0];
  if (!meaning.definitions || meaning.definitions.length === 0) {
    throw new Error('No definitions found in meaning data');
  }
  const defObj = meaning.definitions[0];
  if (!defObj.definition) {
    throw new Error('Definition field missing');
  }
  return defObj.definition;
}

/**
 * Translates the supplied text to the target language using LibreTranslate.
 * @param {string} text - Text to translate.
 * @param {string} targetLang - Target language code (e.g., "lv" for Latvian).
 * @returns {Promise<string>} - A promise that resolves to the translated text.
 * @throws {Error} - If the translation request fails.
 */
export async function translateText(text, targetLang) {
  if (!text) {
    throw new Error('Text to translate must be a non‑empty string');
  }
  if (!targetLang) {
    throw new Error('Target language code must be provided');
  }
  const url = 'https://libretranslate.com/translate';
  const payload = {
    q: text,
    source: 'en',
    target: targetLang,
    format: 'text',
  };
  const response = await fetch(url, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
    },
    body: JSON.stringify(payload),
  });
  if (!response.ok) {
    const errBody = await response.text();
    throw new Error(`Translation request failed: ${response.status} ${response.statusText} – ${errBody}`);
  }
  const data = await response.json();
  if (!data || typeof data.translatedText !== 'string') {
    throw new Error('Invalid translation response format');
  }
  return data.translatedText;
}
